# Problem: find a dictionary word that is an anagram of the scrambled letters.
# Sort the target letters once; compare each candidate by sorted form.
def unscramble(letters, dictionary):
    target = sorted(letters)
    for word in dictionary:
        if sorted(word) == target:
            return word
    return None
```

