# Problem: classic Caesar shift cipher, case-preserving, non-letters untouched.
# Per-character: case-aware modular shift; map to ord/chr in the right range.
def caesar_cipher(s, shift):
    out = []
    for c in s:
        if c.isupper():
            out.append(chr((ord(c) - 65 + shift) % 26 + 65))
        elif c.islower():
            out.append(chr((ord(c) - 97 + shift) % 26 + 97))
        else:
            out.append(c)
    return ''.join(out)
```

