# Problem: per-character document frequency across a list of words.
# Walk each word's unique-character set; bump a counter per distinct char.
def character_frequency(words):
    counts = {}
    for w in words:
        for c in set(w):
            counts[c] = counts.get(c, 0) + 1
    return counts
```

