# Problem: longest shared prefix across all words; empty when none share.
# Zip across all words character-wise; keep characters that are all equal.
def longest_common_prefix(words):
    if not words:
        return ''
    out = []
    for chars in zip(*words):
        if all(c == chars[0] for c in chars):
            out.append(chars[0])
        else:
            break
    return ''.join(out)
```

