# Problem: detect whether the string uses all 26 letters.
# Lowercase, drop non-letters, compare the set of seen letters to a-z.
def is_pangram(s):
    return set(c for c in s.lower() if c.isalpha()) >= set('abcdefghijklmnopqrstuvwxyz')
