# Problem: validate a word-ladder chain (one-letter steps).
# Compare each pair; count char diffs and require exactly one.
def word_ladder_valid(chain):
    for a, b in zip(chain, chain[1:]):
        if len(a) != len(b):
            return False
        diffs = sum(1 for x, y in zip(a, b) if x != y)
        if diffs != 1:
            return False
    return True
```

