# Problem: pick the shortest word, preserving order on ties.
# Walk once tracking the current shortest; equality keeps the earlier one.
def shortest_word(words):
    if not words:
        return ''
    best = words[0]
    for w in words[1:]:
        if len(w) < len(best):
            best = w
    return best
